// General-category data keeps its original u8 kinds and generated bytes.
// Bound the adapter before narrowing; higher Script/scx kinds must never enter it.
fn general_category_kind(kind: u16) -> Option<u8> {
    let first = u16::from(crate::regexp_general_category_data::FIRST_KIND);
    let end = u16::from(crate::regexp_general_category_data::KIND_COUNT);
    if !(first..end).contains(&kind) {
        return None;
    }
    Some(u8::try_from(kind).expect("bounded general-category kind"))
}

fn generic_property_construction_intervals(kind: u16) -> Option<usize> {
    if let Some(kind) = general_category_kind(kind) {
        Some(crate::regexp_general_category_data::construction_intervals(
            kind,
        ))
    } else {
        crate::regexp_script_data::construction_intervals(kind)
            .or_else(|| crate::regexp_script_extensions_data::construction_intervals(kind))
    }
}

// These interval preimages give the same canonical membership as the standalone
// property plan. Under v+i, complements exclude additional fold preimages
// before union and the shared fold closure. Under u+i, complement the raw set.
// Both hex properties have no additional simple/common-fold preimages: uppercase
// members already have lowercase partners. Both u/v complement orders agree.
