    fn word_plan(source: &str, sets: bool, i: bool, m: bool) -> RegExpUnicodeClassMatcher {
        RegExpUnicodeClassMatcher::compile_with_word_boundaries_and_work(
            &JsString::from(source),
            sets,
            i,
            m,
            |_| Ok::<(), std::convert::Infallible>(()),
        )
        .unwrap()
        .unwrap()
    }

