    #[test]
    fn unicode_han_script_membership_over_every_code_point() {
        // Separate UCD raw records, rather than the normalized production ranges.
        let records: &[(u32, u32)] = &[
            (0x2e80, 0x2e99),
            (0x2e9b, 0x2ef3),
            (0x2f00, 0x2fd5),
            (0x3005, 0x3005),
            (0x3007, 0x3007),
            (0x3021, 0x3029),
            (0x3038, 0x303a),
            (0x303b, 0x303b),
            (0x3400, 0x4dbf),
            (0x4e00, 0x9fff),
            (0xf900, 0xfa6d),
            (0xfa70, 0xfad9),
            (0x16fe2, 0x16fe2),
            (0x16fe3, 0x16fe3),
            (0x16ff0, 0x16ff1),
            (0x16ff2, 0x16ff3),
            (0x16ff4, 0x16ff6),
            (0x20000, 0x2a6df),
            (0x2a700, 0x2b81e),
            (0x2b820, 0x2cead),
            (0x2ceb0, 0x2ebe0),
            (0x2ebf0, 0x2ee5d),
            (0x2f800, 0x2fa1d),
            (0x30000, 0x3134a),
            (0x31350, 0x33479),
        ];
        let membership: Vec<_> = (0..=0x10ffff)
            .map(|point| records.iter().any(|(a, b)| *a <= point && point <= *b))
            .collect();
        for name in ["Script=Han", "Script=Hani", "sc=Han", "sc=Hani"] {
            for sets in [false, true] {
                for ignore_case in [false, true] {
                    for form in 0..8 {
                        let source = match form {
                            0 => format!(r"\p{{{name}}}"),
                            1 => format!(r"\P{{{name}}}"),
                            2 => format!(r"[\p{{{name}}}]"),
                            3 => format!(r"[^\p{{{name}}}]"),
                            4 => format!(r"[\P{{{name}}}K]"),
                            5 => format!(r"[\p{{{name}}}K]"),
                            6 => format!(r"[\p{{{name}}}\P{{{name}}}]"),
                            _ => format!(r"[^\P{{{name}}}K]"),
                        };
                        let pattern = JsString::from(source.as_str());
                        let plan = if form < 2 {
                            RegExpUnicodeClassMatcher::compile_binary_property_with_flags(
                                &pattern,
                                sets,
                                ignore_case,
                                false,
                            )
                        } else {
                            RegExpUnicodeClassMatcher::compile_with_flags(
                                &pattern,
                                sets,
                                ignore_case,
                                false,
                            )
                        }
                        .unwrap();
                        for point in 0..=0x10ffff {
                            let han = membership[point as usize];
                            let k =
                                point == 0x4b || (ignore_case && matches!(point, 0x6b | 0x212a));
                            let expected = match form {
                                0 | 2 => han,
                                1 | 3 => !han,
                                4 => !han || k,
                                5 => han || k,
                                6 => true,
                                _ => han && !k,
                            };
                            assert_eq!(
                                plan.matches(point),
                                expected,
                                "{source} v={sets} i={ignore_case} U+{point:X}"
                            );
                        }
                    }
                }
            }
        }
    }

